arguments.command:
TSV="/tmp/asset-monitor-1779287942.tsv"
LOG="/tmp/asset-driver-1779287942.log"

echo "=== RAW TSV (all 48 samples) ==="
column -t -s $'\t' "$TSV" | head -3
echo "..."

echo ""
echo "=== FULL METRICS TABLE ==="
# Print with human timestamps
awk -F'\t' 'NR==1{next} {
  cmd = "date -d @"$1" +%H:%M:%S 2>/dev/null || date -r "$1" +%H:%M:%S 2>/dev/null"
  cmd | getline ts; close(cmd)
  printf "%-10s %-14s CPU=%-3s%% IOW=%-2s%% Rd=%-8s Wr=%-8s RdIOPS=%-5s WrIOPS=%-5s Mem=%sMB\n",
    ts, $2, $3, $4, $6" KB/s", $7" KB/s", $8, $9, $10
}' "$TSV"

echo ""
echo "=== CYCLE TIMING FROM DRIVER LOG ==="
grep -E '\[C[0-9]+\].*(done in|Cycle complete)' "$LOG" | sed 's/\x1b\[[0-9;]*m//g'

echo ""
echo "=== PEAK VALUES ==="
awk -F'\t' 'NR==1{next}{
  if($3+0>maxcpu)  {maxcpu=$3;  maxcpu_ts=$1}
  if($4+0>maxiow)  {maxiow=$4;  maxiow_ts=$1}
  if($6+0>maxrkb)  {maxrkb=$6;  maxrkb_ts=$1}
  if($7+0>maxwkb)  {maxwkb=$7;  maxwkb_ts=$1}
  if($8+0>maxriops){maxriops=$8; maxriops_ts=$1}
  if($9+0>maxwiops){maxwiops=$9; maxwiops_ts=$1}
  sumcpu+=$3; sumrkb+=$6; sumwkb+=$7; n++
} END {
  printf "Peak CPU%%      : %d%%  (t=%s)\n", maxcpu, maxcpu_ts
  printf "Peak IOWait%%   : %d%%  (t=%s)\n", maxiow, maxiow_ts
  printf "Peak Read KB/s : %d    (t=%s)\n", maxrkb, maxrkb_ts
  printf "Peak Write KB/s: %d    (t=%s)\n", maxwkb, maxwkb_ts
  printf "Peak Read IOPS : %d    (t=%s)\n", maxriops, maxriops_ts
  printf "Peak Write IOPS: %d    (t=%s)\n", maxwiops, maxwiops_ts
  printf "\nOverall Avg CPU%%     : %d%%\n", sumcpu/n
  printf "Overall Avg Rd KB/s  : %d\n", sumrkb/n
  printf "Overall Avg Wr KB/s  : %d\n", sumwkb/n
}' "$TSV"
